import random

def randomized_partition(arr: list[int], low: int, high: int) -> int:
    rand_idx = random.randint(low, high)
    arr[rand_idx], arr[high] = arr[high], arr[rand_idx]
    pivot = arr[high]
    i = low - 1
    for j in range(low, high):
        if arr[j] <= pivot:
            i += 1
            arr[i], arr[j] = arr[j], arr[i]
    arr[i + 1], arr[high] = arr[high], arr[i + 1]
    return i + 1

def quick_select(arr: list[int], low: int, high: int, k: int) -> int:
    if low == high: return arr[low]
    p_idx = randomized_partition(arr, low, high)
    if k == p_idx:
        return arr[k]
    elif k < p_idx:
        return quick_select(arr, low, p_idx - 1, k)
    else:
        return quick_select(arr, p_idx + 1, high, k)

